{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum(alloc)
    indices = sorted(range(n), key=lambda i: (-segments[i]['importance'], i))
    for i in indices:
        if remaining <= 0:
            break
        seg = segments[i]
        max_extra = seg['capacity'] - alloc[i]
        if max_extra > 0:
            add = min(remaining, max_extra)
            alloc[i] += add
            remaining -= add
    by_name = {seg['name']: alloc[i] for i, seg in enumerate(segments)}
    total = sum(alloc)
    return {
        "allocations": alloc,
        "by_name": by_name,
        "total": total
    }"
}
